:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --panel: #0f3460;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #a0a0b0;
  --door: #533483;
  --door-open: #e94560;
  --border: #2a2a4a;
  --focus: #f9c74f;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: 'Courier New', monospace;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.elevator-card {
  background: var(--card);
  border: 4px solid var(--border);
  border-radius: 12px;
  padding: 24px;
  width: 100%;
  max-width: 380px;
  box-shadow: 0 8px 0 rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.title {
  text-align: center;
  font-size: 1.5rem;
  letter-spacing: 2px;
  color: var(--accent);
  text-transform: uppercase;
}

.status {
  display: flex;
  justify-content: space-around;
  background: var(--panel);
  border: 3px solid var(--border);
  border-radius: 8px;
  padding: 12px;
}

.status-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.label {
  font-size: 0.75rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.value {
  font-size: 1.5rem;
  font-weight: bold;
  color: var(--text);
}

.doors {
  display: flex;
  height: 100px;
  border: 4px solid var(--border);
  border-radius: 8px;
  overflow: hidden;
  background: var(--panel);
}

.door {
  flex: 1;
  background: var(--door);
  transition: transform 0.3s ease;
}

.door.left {
  border-right: 2px solid var(--border);
}

.door.right {
  border-left: 2px solid var(--border);
}

.doors.open .door.left {
  transform: translateX(-100%);
}

.doors.open .door.right {
  transform: translateX(100%);
}

.panel {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

.floor-btn {
  font-family: inherit;
  font-size: 1.25rem;
  font-weight: bold;
  padding: 16px 0;
  background: var(--panel);
  color: var(--text);
  border: 3px solid var(--border);
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s, box-shadow 0.1s;
  box-shadow: 0 4px 0 var(--border);
}

.floor-btn:hover {
  background: #1a4a7a;
}

.floor-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.floor-btn:active {
  transform: translateY(2px);
  box-shadow: 0 2px 0 var(--border);
}

.floor-btn.queued {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}

.floor-btn.current {
  background: var(--door);
  border-color: var(--door);
}

.hint {
  text-align: center;
  font-size: 0.875rem;
  color: var(--muted);
  line-height: 1.4;
}

@media (max-width: 360px) {
  .elevator-card {
    padding: 16px;
    gap: 16px;
  }
  .floor-btn {
    padding: 12px 0;
    font-size: 1.1rem;
  }
  .value {
    font-size: 1.25rem;
  }
}

(function () {
  'use strict';

  const MIN_FLOOR = 1;
  const MAX_FLOOR = 6;
  const MOVE_INTERVAL = 1000;
  const DOOR_OPEN_DURATION = 2000;

  const state = {
    currentFloor: 1,
    direction: 'idle',
    queue: [],
    moving: false,
    doorsOpen: false,
    doorTimer: null,
    moveTimer: null
  };

  const floorDisplay = document.getElementById('current-floor');
  const directionDisplay = document.getElementById('direction');
  const doorsEl = document.querySelector('.doors');
  const doorLeft = document.getElementById('door-left');
  const doorRight = document.getElementById('door-right');
  const floorButtons = Array.from(document.querySelectorAll('.floor-btn'));

  function updateUI() {
    floorDisplay.textContent = String(state.currentFloor);
    directionDisplay.textContent =
      state.direction === 'up' ? 'Up' :
      state.direction === 'down' ? 'Down' : 'Idle';

    floorButtons.forEach(function (btn) {
      const floor = Number(btn.dataset.floor);
      btn.classList.toggle('queued', state.queue.indexOf(floor) !== -1);
      btn.classList.toggle('current', floor === state.currentFloor);
    });
  }

  function openDoors() {
    if (state.doorsOpen) return;
    state.doorsOpen = true;
    doorsEl.classList.add('open');
    state.doorTimer = setTimeout(function () {
      doorsEl.classList.remove('open');
      state.doorsOpen = false;
      state.doorTimer = null;
      if (!state.moving) {
        state.direction = 'idle';
        updateUI();
      }
    }, DOOR_OPEN_DURATION);
  }

  function closeDoorsImmediately() {
    if (state.doorTimer) {
      clearTimeout(state.doorTimer);
      state.doorTimer = null;
    }
    doorsEl.classList.remove('open');
    state.doorsOpen = false;
  }

  function startMoving() {
    if (state.moving) return;
    state.moving = true;
    state.moveTimer = setInterval(step, MOVE_INTERVAL);
    step();
  }

  function stopMoving() {
    if (state.moveTimer) {
      clearInterval(state.moveTimer);
      state.moveTimer = null;
    }
    state.moving = false;
  }

  function step() {
    if (state.queue.length === 0) {
      stopMoving();
      state.direction = 'idle';
      updateUI();
      return;
    }

    const target = state.queue[0];

    if (target === state.currentFloor) {
      state.queue.shift();
      openDoors();
      updateUI();
      return;
    }

    closeDoorsImmediately();

    if (target > state.currentFloor) {
      state.direction = 'up';
      state.currentFloor += 1;
    } else {
      state.direction = 'down';
      state.currentFloor -= 1;
    }

    updateUI();

    if (state.currentFloor === target) {
      state.queue.shift();
      openDoors();
    }
  }

  function addRequest(floor) {
    if (floor < MIN_FLOOR || floor > MAX_FLOOR) return;
    if (floor === state.currentFloor && !state.moving) {
      openDoors();
      updateUI();
      return;
    }
    if (state.queue.indexOf(floor) !== -1) return;
    state.queue.push(floor);
    updateUI();
    if (!state.moving) {
      startMoving();
    }
  }

  floorButtons.forEach(function (btn) {
    btn.addEventListener('click', function () {
      addRequest(Number(btn.dataset.floor));
    });
  });

  updateUI();
})();
